/* ═══ EMOJI → SVG ICON MAP ═══ */
const EMOJI_MAP={
  "💃":"body","👂":"ear","🏯":"castle","⏰":"clock","⚡":"zap","📜":"scroll","📊":"pulse",
  "🌿":"leaf","📖":"book","☀️":"sun","🎭":"masks","🏛️":"temple",
  "🔥":"flame","💎":"gem","🎬":"film","👑":"crown","⭐":"star",
  "✨":"sparkle","🌬️":"wind","🗣️":"voice","🏋":"body","🏋️":"body",
  "🪞":"mirror","📹":"camera","📋":"clipboard","🔒":"lock",
  "✅":"check","🔄":"refresh","🌙":"moon","🎪":"tent",
  "💭":"thought","🎓":"graduation","✒️":"pen","🧠":"brain",
  "🏃":"run","🏃‍♂️":"run","💡":"lightbulb","🎯":"target","⚔️":"sword",
  "🥁":"drum","👥":"users","🍼":"star","🐣":"leaf",
  "🔍":"search","🕯️":"flame","⚙️":"settings","👻":"sparkle",
  "🎨":"palette","💪":"body","🪵":"temple","🐭":"search",
  "🏆":"trophy","📚":"book","🧪":"brain","🦁":"crown",
  "🌟":"star","🧨":"flame","💫":"sparkle","📺":"tv",
  "🎤":"mic","🎶":"music","🧘":"body","🦋":"leaf",
  "🐉":"flame","💨":"wind","👅":"voice","🥇":"medal",
  "💥":"zap","📅":"cal","🏅":"medal","🎉":"sparkle",
  "🎗️":"medal"
};
function EI({e,s=20,c="#fff"}){
  const key=EMOJI_MAP[e];
  if(key&&I[key])return I[key]({size:s,sw:1.5,style:{color:c}});
  return React.createElement('span',{style:{fontSize:s+'px',lineHeight:1}},e);
}

/* ═══ ICON HELPER ═══ */
const renderIcon=(iconName,props={})=>{
  if(!iconName||typeof iconName!=='string')return null;
  const iconFn=I[iconName];
  return iconFn?iconFn({size:20,...props}):null;
};

/* ═══ CONFETTI ═══ */
function Confetti({count=40,duration=3000,tada=true}){
  const[show,setShow]=useState(()=>{if(window.matchMedia&&window.matchMedia('(display-mode: standalone)').matches||navigator.standalone)return false;return true;});
  const[tadaVisible,setTadaVisible]=useState(tada);
  useEffect(()=>{const t=setTimeout(()=>setShow(false),duration);return()=>clearTimeout(t)},[]);
  useEffect(()=>{if(tada){const t=setTimeout(()=>setTadaVisible(false),2200);return()=>clearTimeout(t)}},[]);
  if(!show&&!tadaVisible)return null;
  const colors=['#C8A44E','#D4B35C','#A78BFA','#8B5CF6','#E8D5A0','#C4B5FD'];
  return(<div style={{position:'fixed',inset:0,pointerEvents:'none',zIndex:200}}>
    {show&&Array.from({length:count}).map((_,i)=>{
      const left=Math.random()*100;const delay=Math.random()*1.5;const dur=2+Math.random()*2;const size=4+Math.random()*8;
      const color=colors[Math.floor(Math.random()*colors.length)];
      const shape=Math.random()>.5?'50%':'2px';
      return <div key={i} className="confetti-piece" style={{left:left+'%',width:size,height:size,background:color,borderRadius:shape,animationDuration:dur+'s',animationDelay:delay+'s'}}/>;
    })}
{/* tada overlay removed — was overlapping with result text */}
  </div>);
}

/* ═══ SPOTLIGHT 3D SVG ═══ */
function Spotlight3D({size=200}){
  return(
    <svg width={size} height={size} viewBox="0 0 200 200" fill="none" style={{filter:'drop-shadow(0 0 40px rgba(200,164,78,.3))'}}>
      {/* Tripod legs */}
      <line x1="100" y1="155" x2="65" y2="198" stroke="#555" strokeWidth="3" strokeLinecap="round"/>
      <line x1="100" y1="155" x2="135" y2="198" stroke="#555" strokeWidth="3" strokeLinecap="round"/>
      <line x1="100" y1="155" x2="100" y2="200" stroke="#666" strokeWidth="3" strokeLinecap="round"/>
      {/* Tripod feet */}
      <circle cx="65" cy="198" r="3" fill="#777"/>
      <circle cx="135" cy="198" r="3" fill="#777"/>
      <circle cx="100" cy="200" r="3" fill="#777"/>
      {/* Pole */}
      <rect x="96" y="105" width="8" height="55" rx="3" fill="linear-gradient(180deg,#888,#555)" />
      <rect x="96" y="105" width="8" height="55" rx="3" fill="#666"/>
      {/* Joint */}
      <circle cx="100" cy="105" r="7" fill="var(--gold-dim)" stroke="var(--gold)" strokeWidth="1"/>
      {/* Lamp body */}
      <rect x="70" y="50" width="60" height="50" rx="6" fill="#2a2a3a" stroke="var(--w10)" strokeWidth="1"/>
      {/* Inner glow */}
      <rect x="74" y="54" width="52" height="42" rx="4" fill="#1a1a26"/>
      {/* Bulb / lens */}
      <circle cx="100" cy="75" r="16" fill="rgba(200,164,78,.15)" stroke="var(--gold)" strokeWidth="1.5"/>
      <circle cx="100" cy="75" r="10" fill="var(--gold)" opacity=".8" style={{animation:'flicker 4s ease-in-out infinite'}}/>
      <circle cx="100" cy="75" r="5" fill="var(--gold-light)"/>
      {/* Barn doors */}
      <rect x="65" y="42" width="15" height="14" rx="2" fill="#3a3a4a" stroke="var(--w08)" strokeWidth=".5" transform="rotate(-15 72 49)"/>
      <rect x="120" y="42" width="15" height="14" rx="2" fill="#3a3a4a" stroke="var(--w08)" strokeWidth=".5" transform="rotate(15 128 49)"/>
      <rect x="82" y="36" width="36" height="10" rx="2" fill="#3a3a4a" stroke="var(--w08)" strokeWidth=".5"/>
      <rect x="82" y="102" width="36" height="8" rx="2" fill="#3a3a4a" stroke="var(--w08)" strokeWidth=".5"/>
      {/* Light ray cone */}
      <path d="M85 50 L40 0 L160 0 L115 50Z" fill="url(#ray-grad)" opacity=".12" style={{animation:'spotlight-ray 4s ease-in-out infinite'}}/>
      <defs>
        <linearGradient id="ray-grad" x1="100" y1="50" x2="100" y2="0" gradientUnits="userSpaceOnUse">
          <stop offset="0%" stopColor="var(--gold)" stopOpacity=".6"/>
          <stop offset="100%" stopColor="var(--gold)" stopOpacity="0"/>
        </linearGradient>
      </defs>
    </svg>
  );
}

/* ═══ SOUND FX ═══ */
const SFX={
  play:(freq=520,dur=.12,type='sine',vol=.04)=>{
    try{
let _sfxCtx=null;
function getSfxCtx(){if(!_sfxCtx)_sfxCtx=new(window.AudioContext||window.webkitAudioContext)();if(_sfxCtx.state==='suspended')_sfxCtx.resume();return _sfxCtx;}
      const ctx=getSfxCtx();
      const osc=ctx.createOscillator();const gain=ctx.createGain();
      const filter=ctx.createBiquadFilter();
      filter.type='lowpass';filter.frequency.value=2000;
      osc.type=type;osc.frequency.value=freq;
      gain.gain.setValueAtTime(vol,ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+dur);
      osc.connect(filter);filter.connect(gain);gain.connect(ctx.destination);
      osc.start(ctx.currentTime);osc.stop(ctx.currentTime+dur);
    }catch(e){}
  },
  xp:()=>{SFX.play(440,.1,'sine',.03);setTimeout(()=>SFX.play(554,.14,'sine',.025),100)},
  success:()=>{SFX.play(392,.08,'sine',.03);setTimeout(()=>SFX.play(494,.08,'sine',.025),110);setTimeout(()=>SFX.play(587,.12,'sine',.03),220)},
  click:()=>SFX.play(330,.04,'sine',.02),
  tap:()=>SFX.play(400,.05,'sine',.02),
  error:()=>{SFX.play(220,.15,'triangle',.03);setTimeout(()=>SFX.play(180,.2,'triangle',.025),120)},
  badge:()=>{SFX.play(523,.1,'sine',.03);setTimeout(()=>SFX.play(659,.1,'sine',.03),120);setTimeout(()=>SFX.play(784,.12,'sine',.03),240);setTimeout(()=>SFX.play(1047,.18,'sine',.025),380)},
  levelUp:()=>{SFX.play(392,.1,'sine',.03);setTimeout(()=>SFX.play(494,.1,'sine',.025),130);setTimeout(()=>SFX.play(587,.1,'sine',.025),260);setTimeout(()=>SFX.play(784,.16,'sine',.03),390)},
  whoosh:()=>{
    try{
      let _sfxCtx=null;
      function getSfxCtx(){if(!_sfxCtx)_sfxCtx=new(window.AudioContext||window.webkitAudioContext)();if(_sfxCtx.state==='suspended')_sfxCtx.resume();return _sfxCtx;}
      const ctx=getSfxCtx();const now=ctx.currentTime;
      /* White noise burst — swoosh texture */
      const bufLen=ctx.sampleRate*0.7;const buf=ctx.createBuffer(1,bufLen,ctx.sampleRate);const d=buf.getChannelData(0);
      for(let i=0;i<bufLen;i++)d[i]=(Math.random()*2-1)*(.6+.4*Math.sin(i/bufLen*Math.PI));
      const noise=ctx.createBufferSource();noise.buffer=buf;
      const noiseGain=ctx.createGain();noiseGain.gain.setValueAtTime(0,now);noiseGain.gain.linearRampToValueAtTime(.06,now+.08);noiseGain.gain.exponentialRampToValueAtTime(.001,now+.7);
      const hp=ctx.createBiquadFilter();hp.type='highpass';hp.frequency.setValueAtTime(800,now);hp.frequency.exponentialRampToValueAtTime(6000,now+.5);
      const lp=ctx.createBiquadFilter();lp.type='lowpass';lp.frequency.value=8000;
      noise.connect(hp);hp.connect(lp);lp.connect(noiseGain);noiseGain.connect(ctx.destination);
      noise.start(now);noise.stop(now+.7);
      /* Rising tone — acceleration feel */
      const osc=ctx.createOscillator();osc.type='sine';osc.frequency.setValueAtTime(200,now);osc.frequency.exponentialRampToValueAtTime(1800,now+.5);
      const oscGain=ctx.createGain();oscGain.gain.setValueAtTime(.025,now);oscGain.gain.linearRampToValueAtTime(.04,now+.15);oscGain.gain.exponentialRampToValueAtTime(.001,now+.55);
      osc.connect(oscGain);oscGain.connect(ctx.destination);osc.start(now);osc.stop(now+.6);
      /* Sparkle chime at the peak */
      setTimeout(()=>{try{const c2=getSfxCtx();const n2=c2.currentTime;const o2=c2.createOscillator();o2.type='sine';o2.frequency.value=1200;const g2=c2.createGain();g2.gain.setValueAtTime(.03,n2);g2.gain.exponentialRampToValueAtTime(.001,n2+.3);o2.connect(g2);g2.connect(c2.destination);o2.start(n2);o2.stop(n2+.3);const o3=c2.createOscillator();o3.type='sine';o3.frequency.value=1600;const g3=c2.createGain();g3.gain.setValueAtTime(.02,n2);g3.gain.exponentialRampToValueAtTime(.001,n2+.25);o3.connect(g3);g3.connect(c2.destination);o3.start(n2);o3.stop(n2+.25)}catch(e){}},200);
    }catch(e){}
  },
};

/* ═══ CGU COMPONENT ═══ */
function CGU({onClose}){
  return(
    <div className="fade-up" style={{minHeight:'100vh',background:'var(--bg)',padding:'28px 20px calc(120px + env(safe-area-inset-bottom))'}}>
      <div className="mw">
        <button onClick={onClose} style={{display:'flex',alignItems:'center',gap:5,color:'var(--text-3)',fontSize:12,marginBottom:20}}>{I.chL({size:16})} Retour</button>
        <h1 className="heading" style={{fontSize:24,marginBottom:4}}>Conditions Générales d'Utilisation</h1>
        <p className="body" style={{fontSize:10,marginBottom:18}}>Dernière mise à jour : mars 2026</p>
        <div className="cgu-content">
          <h3>1. Éditeur de l'application</h3>
          <p>Castigat Academy est édité par la Compagnie Castigat, compagnie de théâtre basée à Paris. Contact : contact@compagniecastigat.fr</p>

          <h3>2. Objet</h3>
          <p>Castigat Academy est une application d'enseignement du théâtre en ligne proposant des exercices, des leçons de culture théâtrale, un parcours de progression et un suivi pédagogique. Les présentes CGU régissent l'utilisation de l'application.</p>

          <h3>3. Inscription et compte</h3>
          <p>L'inscription requiert la fourniture d'un prénom, nom, date de naissance et adresse email. L'utilisateur·ice garantit l'exactitude des informations fournies. L'application est destinée aux personnes de 16 ans et plus. Les mineur·e·s de 16 à 18 ans doivent disposer de l'autorisation de leur représentant légal.</p>

          <h3>4. Données personnelles</h3>
          <p>Les données collectées (prénom, nom, date de naissance, email, progression pédagogique) sont utilisées exclusivement pour le fonctionnement de l'application et le suivi pédagogique. Elles ne sont ni vendues ni transmises à des tiers. Conformément au RGPD, vous disposez d'un droit d'accès, de rectification et de suppression de vos données. Pour exercer ce droit : contact@compagniecastigat.fr</p>

          <h3>5. Utilisation du microphone</h3>
          <p>Certaines fonctionnalités (échauffement vocal, exercices de diction) peuvent utiliser le microphone de votre appareil. L'accès au microphone est soumis à votre consentement explicite via la demande de permission du navigateur. Les données audio sont traitées localement sur votre appareil et ne sont ni enregistrées ni transmises à nos serveurs.</p>

          <h3>6. Abonnement Premium</h3>
          <p>L'application propose un accès gratuit (exercices de base, culture, progression) et un abonnement Premium donnant accès aux outils du comédien, aux monologues classiques avec retour professionnel, aux fonctionnalités sociales et au contenu exclusif. Le tarif et les modalités de paiement sont précisés lors de la souscription. Droit de rétractation de 14 jours à compter de la souscription, conformément au Code de la consommation.</p>

          <h3>7. Propriété intellectuelle</h3>
          <p>L'ensemble des contenus de l'application (exercices, textes originaux, illustrations, design, code) est la propriété de la Compagnie Castigat. Les extraits d'œuvres du domaine public (Molière, Shakespeare, Racine, etc.) sont utilisés à des fins pédagogiques. Toute reproduction non autorisée est interdite.</p>

          <h3>8. Vidéos et contenus utilisateur</h3>
          <p>Les vidéos soumises pour feedback restent la propriété de l'utilisateur·ice. La Compagnie Castigat s'engage à les utiliser uniquement dans le cadre du retour pédagogique, sauf autorisation expresse pour toute autre utilisation.</p>

          <h3>9. Limitation de responsabilité</h3>
          <p>Castigat Academy est un outil pédagogique complémentaire et ne remplace pas une formation professionnelle diplômante. La Compagnie Castigat ne saurait être tenue responsable des interruptions techniques, pertes de données ou résultats pédagogiques.</p>

          <h3>10. Résiliation</h3>
          <p>L'utilisateur·ice peut supprimer son compte et ses données à tout moment depuis l'application ou par email. La résiliation de l'abonnement Premium prend effet à la fin de la période en cours.</p>

          <h3>11. Droit applicable</h3>
          <p>Les présentes CGU sont soumises au droit français. Tout litige relève de la compétence exclusive des tribunaux de Paris.</p>

          <h3>12. Contact</h3>
          <p>Pour toute question : contact@compagniecastigat.fr — Compagnie Castigat, Paris, France.</p>
        </div>
        <button onClick={onClose} className="btn-gold" style={{width:'100%',padding:'13px 0',fontSize:12,marginTop:16}}>J'ai compris</button>
      </div>
    </div>
  );
}

