const TOUTES_SEANCES=[SEANCES,SEANCES_A2,SEANCES_N3,SEANCES_N4,SEANCES_N5,SEANCES_N6,SEANCES_N7,SEANCES_N8,SEANCES_N9,SEANCES_N10,SEANCES_N11,SEANCES_N12];
/* Chaque séance porte sa leçon de culture en cinquième temps : c'est là,
   et nulle part ailleurs, qu'on apprend quelque chose sur le théâtre. Le
   catalogue Culture séparé n'est plus ouvrable depuis la suppression de
   l'onglet ; il reste dans le fichier, en réserve, mais plus rien ne le
   compte. */
function leconsDeCulture(st){
  const tf=(st&&st.tempsFaits)||{};let n=0;
  for(const lot of TOUTES_SEANCES)for(const S of lot){
    const k=(S.temps||[]).findIndex(t=>t.dom==="cu");
    if(k>=0&&(tf[S.id]||[]).includes(k))n++;
  }
  return n;
}
const SEANCE_PAR_ID=(()=>{const m={};for(const lot of TOUTES_SEANCES)for(const s of lot)m[s.id]=s;return m})();

/* ═══ LE CARNET — les traces restent sur l'appareil ═══ */
const CARNET_DB="castigat_carnet";
function carnetOuvrir(){
  return new Promise((res,rej)=>{
    try{
      const r=indexedDB.open(CARNET_DB,1);
      r.onupgradeneeded=()=>{const db=r.result;if(!db.objectStoreNames.contains("traces"))db.createObjectStore("traces",{keyPath:"id"})};
      r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);
    }catch(e){rej(e)}
  });
}
async function carnetPoser(t){
  const db=await carnetOuvrir();
  return new Promise((res,rej)=>{const tx=db.transaction("traces","readwrite");
    tx.objectStore("traces").put(t);tx.oncomplete=()=>res(true);tx.onerror=()=>rej(tx.error)});
}
async function carnetLire(){
  const db=await carnetOuvrir();
  return new Promise((res,rej)=>{const tx=db.transaction("traces","readonly");
    const q=tx.objectStore("traces").getAll();
    q.onsuccess=()=>res((q.result||[]).sort((a,b)=>b.date.localeCompare(a.date)));q.onerror=()=>rej(q.error)});
}
async function carnetEffacer(id){
  const db=await carnetOuvrir();
  return new Promise((res,rej)=>{const tx=db.transaction("traces","readwrite");
    tx.objectStore("traces").delete(id);tx.oncomplete=()=>res(true);tx.onerror=()=>rej(tx.error)});
}

/* Le lecteur maison : la barre blanche du navigateur n'a rien à faire ici. */
function Lecteur({src}){
  const ref=useRef(null);
  const[joue,setJoue]=useState(false);
  const[t,setT]=useState(0);
  const[total,setTotal]=useState(0);
  const maj=()=>{const a=ref.current;if(!a)return;setT(a.currentTime);
    if(isFinite(a.duration)&&a.duration>0)setTotal(a.duration);else setTotal(v=>Math.max(v,a.currentTime))};
  const bascule=()=>{const a=ref.current;if(!a)return;
    if(a.paused){a.play().then(()=>setJoue(true)).catch(()=>{})}else{a.pause();setJoue(false)}};
  const f=total>0?Math.min(1,t/total):0;
  return(
    <div style={{display:'flex',alignItems:'center',gap:13,padding:'11px 13px',borderRadius:12,background:'var(--w03)',border:'1px solid var(--line)'}}>
      <audio ref={ref} src={src} preload="metadata" onTimeUpdate={maj} onLoadedMetadata={maj}
        onEnded={()=>{setJoue(false);setT(0)}} style={{display:'none'}}/>
      <button onClick={bascule} aria-label={joue?"Pause":"Écouter"}
        style={{flexShrink:0,width:38,height:38,borderRadius:'50%',border:'1px solid var(--line-s)',cursor:'pointer',
          background:'var(--gold-glow)',color:'var(--gold)',display:'flex',alignItems:'center',justifyContent:'center'}}>
        {joue
          ?<svg width="13" height="14" viewBox="0 0 13 14" fill="currentColor"><rect x="0" y="0" width="4" height="14" rx="1"/><rect x="9" y="0" width="4" height="14" rx="1"/></svg>
          :<svg width="13" height="14" viewBox="0 0 13 14" fill="currentColor" style={{marginLeft:2}}><path d="M0 1.2c0-1 1.1-1.6 1.9-1L12.4 6.2c.8.5.8 1.6 0 2.1L1.9 13.8c-.8.5-1.9 0-1.9-1z"/></svg>}
      </button>
      <div style={{flex:1,minWidth:0}}>
        <div style={{height:3,borderRadius:3,background:'var(--w06)',overflow:'hidden'}}>
          <div style={{height:'100%',width:(f*100)+'%',background:'var(--gold)',transition:'width .18s linear'}}/>
        </div>
        <p style={{fontSize:9.5,color:'var(--text-3)',marginTop:6,fontVariantNumeric:'tabular-nums'}}>{fmtDur(t)}{total>0?" / "+fmtDur(total):""}</p>
      </div>
    </div>
  );
}

/* ═══ L'ENREGISTREUR ═══
   Le micro et la caméra ne sont pas toujours disponibles (aperçu ouvert
   depuis un fichier, permission refusée). On retombe alors sur l'appareil
   photo du téléphone, puis sur une simple confirmation. */
function Enregistreur({type,secs,onPret,onEfface}){
  const[phase,setPhase]=useState("pret");/* pret · enregistre · relu · refus */
  const[reste,setReste]=useState(secs||30);
  const[url,setUrl]=useState(null);
  const blobRef=useRef(null),recRef=useRef(null),fluxRef=useRef(null),apercuRef=useRef(null),tickRef=useRef(null);
  const video=type==="video";

  const stopFlux=()=>{if(fluxRef.current){fluxRef.current.getTracks().forEach(t=>t.stop());fluxRef.current=null}};
  useEffect(()=>()=>{stopFlux();if(tickRef.current)clearInterval(tickRef.current);if(url)URL.revokeObjectURL(url)},[]);

  const arreter=()=>{try{recRef.current&&recRef.current.state!=="inactive"&&recRef.current.stop()}catch(e){}};

  const demarrer=async()=>{
    if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia||typeof MediaRecorder==="undefined"){setPhase("refus");return}
    try{
      const flux=await navigator.mediaDevices.getUserMedia(video?{audio:true,video:{facingMode:"user"}}:{audio:true});
      fluxRef.current=flux;
      if(video&&apercuRef.current){apercuRef.current.srcObject=flux;apercuRef.current.play().catch(()=>{})}
      const mr=new MediaRecorder(flux);recRef.current=mr;
      const morceaux=[];
      mr.ondataavailable=e=>{if(e.data&&e.data.size)morceaux.push(e.data)};
      mr.onstop=()=>{
        clearInterval(tickRef.current);stopFlux();
        const b=new Blob(morceaux,{type:video?"video/webm":"audio/webm"});
        blobRef.current=b;setUrl(URL.createObjectURL(b));setPhase("relu");SFX.success&&SFX.success();
      };
      mr.start();setPhase("enregistre");setReste(secs||30);SFX.tap&&SFX.tap();
      tickRef.current=setInterval(()=>setReste(r=>{if(r<=1){arreter();return 0}return r-1}),1000);
    }catch(e){setPhase("refus")}
  };

  const fichier=(e)=>{
    const f=e.target.files&&e.target.files[0];if(!f)return;
    blobRef.current=f;setUrl(URL.createObjectURL(f));setPhase("relu");
  };

  const refaire=()=>{if(url)URL.revokeObjectURL(url);setUrl(null);blobRef.current=null;setPhase("pret");onEfface&&onEfface()};

  const anneau=(()=>{const t=secs||30,f=Math.max(0,Math.min(1,reste/t)),R=34,C=2*Math.PI*R;
    return{R,C,off:C*(1-f)}})();

  return(
    <div className="card" style={{padding:20,textAlign:'center',borderColor:phase==="enregistre"?'var(--coral)':'var(--line-s)',transition:'border-color .3s'}}>
      {video&&(phase==="enregistre")&&(
        <video ref={apercuRef} muted playsInline
          style={{width:'100%',maxWidth:230,borderRadius:14,marginBottom:14,transform:'scaleX(-1)',background:'#000'}}/>
      )}

      {phase==="pret"&&(<>
        <div style={{width:62,height:62,borderRadius:'50%',margin:'0 auto 14px',display:'flex',alignItems:'center',justifyContent:'center',
          background:'var(--gold-glow)',border:'1px solid var(--line-s)',color:'var(--gold)'}}>
          {video?I.camera({size:24,sw:1.5}):I.mic({size:24,sw:1.5})}
        </div>
        <p style={{fontSize:11,color:'var(--text-3)',marginBottom:14}}>{secs||30} secondes · rien ne quitte votre téléphone</p>
        <button onClick={demarrer} className="btn-gold" style={{padding:'13px 34px',fontSize:12.5}}>Enregistrer</button>
      </>)}

      {phase==="enregistre"&&(<>
        <div style={{position:'relative',width:84,height:84,margin:'0 auto 12px'}}>
          <svg width="84" height="84" style={{transform:'rotate(-90deg)'}}>
            <circle cx="42" cy="42" r={anneau.R} fill="none" stroke="var(--w06)" strokeWidth="3"/>
            <circle cx="42" cy="42" r={anneau.R} fill="none" stroke="var(--coral)" strokeWidth="3"
              strokeDasharray={anneau.C} strokeDashoffset={anneau.off} strokeLinecap="round" style={{transition:'stroke-dashoffset 1s linear'}}/>
          </svg>
          <div style={{position:'absolute',inset:0,display:'flex',alignItems:'center',justifyContent:'center'}}>
            <span className="heading" style={{fontSize:22,color:'var(--coral)'}}>{reste}</span>
          </div>
        </div>
        <p className="eb" style={{color:'var(--coral)',marginBottom:14,animation:'pulse-rec 1.3s ease-in-out infinite'}}>Enregistrement</p>
        <button onClick={arreter} className="btn-outline" style={{padding:'11px 26px',fontSize:11}}>Arrêter maintenant</button>
      </>)}

      {phase==="relu"&&(<>
        {video
          ?<video src={url} controls playsInline style={{width:'100%',maxWidth:230,borderRadius:14,marginBottom:14,background:'#000'}}/>
          :<div style={{marginBottom:14}}><Lecteur src={url}/></div>}
        <div style={{display:'flex',gap:9,justifyContent:'center'}}>
          <button onClick={refaire} className="btn-outline" style={{padding:'10px 20px',fontSize:11}}>Refaire</button>
          <button onClick={()=>onPret&&onPret(blobRef.current)} className="pill" style={{padding:'10px 24px'}}>Garder dans le carnet</button>
        </div>
      </>)}

      {phase==="refus"&&(<>
        <p style={{fontSize:12,color:'var(--text-2)',lineHeight:1.6,marginBottom:14}}>
          Le {video?"caméra":"micro"} n'est pas accessible ici. Enregistrez avec votre téléphone, puis reprenez le fichier — ou passez, la séance compte quand même.
        </p>
        <label style={{display:'block',cursor:'pointer',marginBottom:10}}>
          <input type="file" accept={video?"video/*":"audio/*"} capture="user" style={{display:'none'}} onChange={fichier}/>
          <span className="pill" style={{display:'inline-block',padding:'11px 24px'}}>Choisir un enregistrement</span>
        </label>
        <button onClick={()=>onPret&&onPret(null)} style={{fontSize:11,color:'var(--text-3)',background:'none',border:'none',cursor:'pointer',fontWeight:700,padding:'6px 0'}}>Je l'ai fait sans enregistrer</button>
      </>)}
    </div>
  );
}

/* Les cinq temps d'une séance sont désormais portés par les données
   elles-mêmes (S.temps), un par domaine : plus de liste figée ici. */

/* Pendant l'écran de fin d'une séance, rien ne doit s'empiler par-dessus :
   le badge attend en coulisse et entre quand la scène est libre. */
const ECRAN={fin:false,liberer:null};

/* ═══ CE QUI EST FAIT AUJOURD'HUI ═══
   Les anciennes catégories se rangent dans les cinq domaines : l'écran du
   jour dit la même chose que le parcours, quel que soit le niveau. */
const DOM_DE_CAT={Voix:"v",Respiration:"v",Diction:"v",Corps:"c",
  Texte:"t",Monologue:"t","Scène":"t",Jeu:"j",Intentions:"j",Improvisation:"j",Pro:"j",Culture:"cu"};
const DOM_ORDRE=[["v","Voix"],["c","Corps"],["t","Texte"],["j","Jeu"],["cu","Culture"]];

function domainesDuJour(st){
  const jour=new Date().toISOString().slice(0,10);
  const faits=new Set();
  const m=st.catLastPracticed||{};
  for(const cat in m){
    const d=DOM_DE_CAT[cat];
    if(d&&String(m[cat]).slice(0,10)===jour)faits.add(d);
  }
  return faits;
}

function DomainesDuJour({st}){
  const faits=domainesDuJour(st);
  return(
    <div style={{marginBottom:22}}>
      <div className="sep">
        <b>Fait aujourd'hui</b>
        <b style={{color:faits.size?'var(--gold)':'var(--text-3)',letterSpacing:'.06em'}}>{faits.size} / 5</b>
        <i/>
      </div>
      <div style={{display:'flex',gap:7}}>
        {DOM_ORDRE.map(([id,nom])=>{
          const ok=faits.has(id);
          return(
            <div key={id} style={{flex:1,padding:'12px 3px 10px',borderRadius:13,textAlign:'center',
              background:ok?'rgba(224,184,78,.10)':'var(--w02)',
              border:'1px solid '+(ok?'rgba(224,184,78,.30)':'var(--line)'),
              transition:'background .4s ease,border-color .4s ease'}}>
              <span style={{height:19,display:'flex',alignItems:'center',justifyContent:'center',
                color:ok?'var(--gold)':'var(--text-3)'}}>
                {ok
                  ?I.check({size:16,sw:2.4})
                  :<span style={{width:8,height:8,borderRadius:'50%',border:'1.5px solid var(--line-s)',display:'block'}}/>}
              </span>
              <span style={{display:'block',fontSize:9,fontWeight:700,marginTop:6,letterSpacing:'.05em',
                color:ok?'var(--text)':'var(--text-3)'}}>{nom}</span>
            </div>
          );
        })}
      </div>
    </div>
  );
}

/* ── La culture dans la séance ────────────────────────────────────────
   Elle était expédiée : quatre paragraphes empilés dans une carte et un
   quiz collé dessous, lu en trente secondes. L'onglet Culture, lui, avait
   une vraie mise en scène — le grand dessin, la lecture page par page, le
   quiz qui corrige. Cet onglet n'existe plus : sa mise en scène vient ici.
   On lit une page à la fois, on répond, on se trompe et on apprend. */
function TempsCulture({T,S,teinte,onValider,labelFin}){
  const[ph,setPh]=useState("lecture");   /* lecture | quiz | fin */
  const[pg,setPg]=useState(0);
  const[qi,setQi]=useState(0);
  const[sc,setSc]=useState(0);
  const[sel,setSel]=useState(null);
  const[corr,setCorr]=useState(false);
  const pages=T.texte||[];
  const quiz=T.quiz||[];
  const dessin=T.dessin||"origines";
  const scRef=useRef(0);

  const suiteQuiz=(ns)=>{
    setSel(null);setCorr(false);
    if(qi<quiz.length-1)setQi(qi+1);
    else{setPh("fin");SFX.success&&SFX.success()}
  };
  const repondre=(i)=>{
    if(sel!==null)return;
    setSel(i);
    const ok=i===quiz[qi].a;
    const ns=ok?sc+1:sc;setSc(ns);scRef.current=ns;
    if(ok){SFX.success&&SFX.success();setTimeout(()=>suiteQuiz(ns),850)}
    else{SFX.play&&SFX.play(220,.2,'triangle',.03);setCorr(true)}
  };

  /* Le bandeau illustré : c'est lui qui donne à la leçon son air de leçon
     plutôt que de pense-bête. Le dessin déborde du cadre, comme sur les
     cartes de niveau. */
  const bandeau=(
    <div className="ill-card ic-violet" style={{marginBottom:16,minHeight:122}}>
      <img src={`img/c/${dessin}.svg`} alt="" aria-hidden="true" decoding="async"
        onError={e=>{e.target.style.display='none'}}
        style={{position:'absolute',right:-16,bottom:-12,width:158,height:158,objectFit:'contain',zIndex:2,pointerEvents:'none'}}/>
      <span className="ill-in" style={{padding:'17px 17px 16px'}}>
        <span className="eb" style={{color:'var(--violet)'}}>La culture</span>
        <span className="heading" style={{display:'block',fontSize:20,marginTop:5,maxWidth:200}}>{T.titre}</span>
        {T.pourquoi&&<span style={{display:'block',fontSize:10.5,color:'rgba(242,240,234,.62)',marginTop:6,maxWidth:190,lineHeight:1.5}}>{T.pourquoi}</span>}
      </span>
    </div>
  );

  if(ph==="lecture")return(
    <div className="temps">
      {bandeau}
      <div style={{marginBottom:12}}>
        <Bar val={pg+1} max={pages.length||1} cls="fill-violet" h={2.5}/>
        <p style={{fontSize:8.5,color:'var(--text-3)',marginTop:5,textAlign:'right'}}>{pg+1} / {pages.length}</p>
      </div>
      <div className="card" style={{padding:'24px 22px',minHeight:190,display:'flex',flexDirection:'column',justifyContent:'space-between'}}>
        <p key={pg} className="body fade-up" style={{fontSize:14.5,lineHeight:1.9,color:'var(--text)',fontWeight:400}}>{pages[pg]}</p>
        <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginTop:22,gap:10}}>
          <button onClick={()=>setPg(Math.max(0,pg-1))} className="btn-outline"
            style={{padding:'9px 15px',fontSize:11,opacity:pg===0?.28:1,pointerEvents:pg===0?'none':'auto'}}>←</button>
          {pg<pages.length-1
            ?<button onClick={()=>{setPg(pg+1);SFX.tap&&SFX.tap()}} className="pill">Suivant</button>
            :<button onClick={()=>{quiz.length?setPh("quiz"):setPh("fin");SFX.tap&&SFX.tap()}} className="pill">
               {quiz.length?"Passer au quiz":"J'ai lu"}</button>}
        </div>
      </div>
    </div>
  );

  if(ph==="quiz"){
    const q=quiz[qi];
    return(
      <div className="temps">
        {bandeau}
        <button onClick={()=>{setPh("lecture");setQi(0);setSc(0);setSel(null);setCorr(false)}}
          style={{display:'flex',alignItems:'center',gap:5,color:'var(--text-3)',fontSize:10.5,marginBottom:11,
            background:'none',border:'none',cursor:'pointer',padding:0}}>{I.chL({size:13})} Revoir la leçon</button>
        <div style={{marginBottom:12}}>
          <Bar val={qi+1} max={quiz.length} cls="fill-violet" h={2.5}/>
          <p style={{fontSize:8.5,color:'var(--text-3)',marginTop:5,textAlign:'right'}}>Question {qi+1} / {quiz.length}</p>
        </div>
        <div className="card" style={{padding:'22px 20px'}}>
          <h3 className="heading" style={{fontSize:16.5,marginBottom:16,lineHeight:1.35}}>{q.q}</h3>
          {q.o.map((o,i)=>{
            const bon=i===q.a,choisi=sel===i,montre=sel!==null;
            return(
              <button key={i} disabled={montre} onClick={()=>repondre(i)}
                style={{width:'100%',textAlign:'left',padding:'12px 14px',marginBottom:8,borderRadius:11,
                  cursor:montre?'default':'pointer',fontSize:12.5,lineHeight:1.45,transition:'all .25s',
                  display:'flex',alignItems:'center',gap:9,
                  background:montre&&bon?'rgba(52,211,153,.10)':montre&&choisi?'rgba(224,120,100,.10)':'var(--w03)',
                  border:'1.5px solid '+(montre&&bon?'var(--emerald)':montre&&choisi?'var(--coral)':'var(--line)'),
                  color:montre&&(bon||choisi)?'var(--text)':'var(--text-2)',fontWeight:montre&&bon?700:500}}>
                <span style={{fontSize:9,fontWeight:700,color:'var(--violet)',flexShrink:0}}>{String.fromCharCode(65+i)}</span>
                <span style={{flex:1}}>{o}</span>
                {montre&&bon&&<span style={{color:'var(--emerald)',display:'flex'}}>{I.check({size:13,sw:2.4})}</span>}
              </button>
            );
          })}
          {corr&&(
            <div className="fade-up" style={{marginTop:14,padding:'14px 16px',borderRadius:11,
              background:'rgba(52,211,153,.05)',border:'1px solid rgba(52,211,153,.14)'}}>
              <p style={{fontSize:10,fontWeight:700,color:'var(--emerald)',marginBottom:5}}>La bonne réponse</p>
              <p style={{fontSize:12.5,color:'var(--text)',fontWeight:700,lineHeight:1.45,marginBottom:12}}>{q.o[q.a]}</p>
              <button onClick={()=>suiteQuiz(scRef.current)} className="btn-gold"
                style={{width:'100%',padding:'11px 0',fontSize:11.5}}>Continuer</button>
            </div>
          )}
        </div>
      </div>
    );
  }

  /* Fin de la leçon : le score, puis on valide le temps. */
  const parfait=quiz.length>0&&sc===quiz.length;
  return(
    <div className="temps" style={{textAlign:'center',paddingTop:8}}>
      {parfait&&<Confetti count={22} duration={2000}/>}
      <div style={{position:'relative',width:126,height:126,margin:'0 auto 4px'}}>
        <div style={{position:'absolute',inset:0,borderRadius:'50%',
          background:'radial-gradient(circle at 50% 60%,rgba(184,160,224,.22),rgba(184,160,224,.05) 58%,transparent 72%)'}}/>
        <div style={{position:'absolute',inset:0,borderRadius:'50%',border:'1px solid rgba(184,160,224,.22)'}}/>
        <img src={`img/c/${dessin}.svg`} alt="" aria-hidden="true" decoding="async"
          onError={e=>{e.target.parentNode.style.display='none'}}
          style={{position:'absolute',inset:'9px',width:'calc(100% - 18px)',height:'calc(100% - 18px)',objectFit:'contain'}}/>
      </div>
      <p className="eb" style={{color:'var(--violet)',marginTop:14}}>Leçon lue</p>
      <h3 className="heading" style={{fontSize:20,margin:'8px 0 0'}}>{T.titre}</h3>
      {quiz.length>0&&(
        <p className="heading gold-shimmer" style={{fontSize:19,marginTop:12}}>{sc} / {quiz.length}</p>
      )}
      {T.retenir&&(
        <div className="card" style={{padding:'16px 18px',marginTop:18,textAlign:'left',borderColor:'var(--line-s)',
          background:'linear-gradient(120deg,rgba(184,160,224,.07),var(--bg-card) 72%)'}}>
          <p className="eb" style={{color:'var(--violet)',marginBottom:7}}>Ce qu'il faut retenir</p>
          <p className="body" style={{fontSize:12.5,lineHeight:1.7,color:'var(--text-2)'}}>{T.retenir}</p>
        </div>
      )}
      <button onClick={onValider} className="btn-gold"
        style={{width:'100%',padding:'14px 0',fontSize:12.5,marginTop:22}}>{labelFin}</button>
    </div>
  );
}

/* ── L'entrée en scène du coach ───────────────────────────────────────
   Deux secondes avant chaque exercice : la couleur du domaine envahit
   l'écran, le coach se présente, une phrase, et on y va. C'est ce qui
   transforme « encore un écran de texte » en « le cours commence ».
   Un tap n'importe où passe directement. */
function IntroCoach({T,S,st,onGo}){
  const D=DOMAINES[T.dom]||DOMAINES.v;
  const SC=SCENES[T.dom]||SCENES.v;
  /* Pas de minuteur : on lit à son rythme, et on part quand on est prêt.
     La première version passait toute seule au bout de trois secondes —
     trop court pour lire, et rien de pire qu'un écran qui vous échappe. */
  return(
    <div style={{position:'fixed',inset:0,zIndex:60,
      background:`radial-gradient(120% 70% at 50% 108%, color-mix(in srgb, ${D.teinte} 26%, transparent), transparent 70%), var(--bg)`,
      display:'flex',flexDirection:'column',alignItems:'center',justifyContent:'center',
      padding:'40px 30px',textAlign:'center',animation:'fadeIn .35s ease both'}}>

      {/* Votre personnage, dessiné en train de faire l'exercice : le corps
          est dans la scène, la tête est votre avatar, posée dessus. */}
      <div style={{position:'relative',width:'min(280px,76vw)',aspectRatio:'240/180',
        animation:'fadeUp .7s cubic-bezier(.22,1,.36,1) .05s both'}}>
        <div style={{position:'absolute',inset:0,borderRadius:20,overflow:'visible',
          background:`linear-gradient(160deg, color-mix(in srgb, ${D.teinte} 18%, var(--bg-card)), var(--bg-card) 76%)`,
          border:`1px solid color-mix(in srgb, ${D.teinte} 32%, transparent)`,
          boxShadow:`0 18px 50px color-mix(in srgb, ${D.teinte} 16%, transparent)`}}/>
        <img src={`img/${SC.src}`} alt="" aria-hidden="true" decoding="async"
          onError={e=>{e.target.style.display='none'}}
          style={{position:'absolute',inset:0,width:'100%',height:'100%',objectFit:'cover',
            borderRadius:20,border:`1px solid color-mix(in srgb, ${D.teinte} 32%, transparent)`,
            animation:'fadeUp .7s cubic-bezier(.22,1,.36,1) .25s both'}}/>
        <span className="eb" style={{position:'absolute',top:12,left:14,color:D.teinte}}>{D.long}</span>
      </div>
      <h2 className="heading" style={{fontSize:'clamp(23px,6.6vw,29px)',lineHeight:1.12,margin:'10px 0 0',
        animation:'fadeUp .7s cubic-bezier(.22,1,.36,1) .6s both'}}>{T.titre}</h2>
      {/* L'idée de l'exercice : dite franchement, pas soufflée. Elle était en
          petit italique entre guillemets — on la lisait comme une citation
          décorative au lieu de la lire tout court. */}
      <div style={{width:34,height:2,borderRadius:2,background:D.teinte,opacity:.85,margin:'16px auto 0',
        animation:'trait-ouvre .6s ease .75s both'}}/>
      <p style={{fontSize:16,fontWeight:600,lineHeight:1.55,color:'var(--text)',marginTop:12,maxWidth:310,
        animation:'fadeUp .7s ease .8s both'}}>
        {T.pourquoi||D.intro}
      </p>

      <button onClick={()=>{SFX.tap&&SFX.tap();onGo()}} className="btn-gold"
        style={{padding:'14px 44px',fontSize:12.5,marginTop:28,
          animation:'btn-scale-in .6s cubic-bezier(.22,1,.36,1) .9s both'}}>C'est parti</button>
    </div>
  );
}

function SeanceV({mod,st,setSt,back,next,onNext,seance,tempsSeul}){
  const S=SEANCE_PAR_ID[mod.id]||mod;
  const TS=S.temps||[];
  const n=TS.length;
  /* Une séance au format cinq temps se fait TOUJOURS un exercice à la fois :
     on en ouvre un, on le fait, il se valide, on revient au menu choisir le
     suivant. Plus rien ne s'enchaîne tout seul, quel que soit l'endroit d'où
     la séance a été ouverte (accueil, programme du niveau, onglet Pratique).
     tempsSeul ne décide que d'une chose : entrer direct sur cet exercice
     plutôt que de passer par le carton d'ouverture. */
  const solo=n>0;
  const direct=Number.isInteger(tempsSeul)&&tempsSeul>=0&&tempsSeul<n;
  const[temps,setTemps]=useState(direct?tempsSeul:-1);  /* -1 = carton d'ouverture, n = la fin */
  /* L'intro du coach : un écran de deux secondes qui annonce le domaine
     avant l'exercice — la couleur, le visage, une phrase. On peut passer
     d'un tap. Rejouée à chaque temps, jamais sur le carton ni la fin. */
  const[intro,setIntro]=useState(direct);
  useEffect(()=>{if(temps>=0&&temps<n)setIntro(true)},[temps]);
  const[reponses,setReponses]=useState({});
  const[quizRep,setQuizRep]=useState({});
  const[traceFaite,setTraceFaite]=useState(false);
  const[traceOuverte,setTraceOuverte]=useState(false);
  const[traceTexte,setTraceTexte]=useState("");
  const[done,setDone]=useState((st.doneEx||[]).includes(S.id));
  const[xpPop,setXpPop]=useState(false);
  const[xpGagne,setXpGagne]=useState(S.xp);
  /* Le palier entre deux temps : on reste dans la séance, on voit ce qu'on
     vient de gagner, et le suivant est à un tap. Rien ne s'enchaîne tout
     seul — mais on ne repasse plus par l'accueil pour continuer. */
  const[palier,setPalier]=useState(null);

  useEffect(()=>{
    ECRAN.fin=(temps===n);
    return()=>{if(ECRAN.fin){ECRAN.fin=false;ECRAN.liberer&&ECRAN.liberer()}};
  },[temps]);

  /* Chaque temps validé coche sa case de domaine sur l'accueil, tout de
     suite — on voit les cinq cases se remplir pendant la séance au lieu
     d'attendre la fin. C'est le seul compteur de l'app qui soit vraiment
     atteignable en une journée. */
  const marquerDomaine=(dom)=>{
    const nom=(DOMAINES[dom]||{}).nom;
    if(!nom)return;
    const now=new Date().toISOString();
    setSt(p=>({...p,catLastPracticed:{...(p.catLastPracticed||{}),[nom]:now}}));
  };

  const finir=()=>{
    if(done)return;
    /* L'XP se verse temps par temps ; ici on solde le reliquat, pour que le
       total donné par la séance fasse exactement S.xp — les paliers de
       niveau n'ont que 5 XP de marge, on ne peut pas en créer. La journée
       compte comme faite ici : sans ça le compteur de séances restait à zéro. */
    const reste=Math.max(0,S.xp-((st.xpSeance||{})[S.id]||0));
    setDone(true);setXpGagne(reste);setXpPop(true);SFX.xp&&SFX.xp();
    setSt(p=>({...p,xp:p.xp+reste,weekXP:(p.weekXP||0)+reste,weekEx:(p.weekEx||0)+1,
      xpSeance:{...(p.xpSeance||{}),[S.id]:S.xp},
      doneEx:(p.doneEx||[]).includes(S.id)?p.doneEx:[...(p.doneEx||[]),S.id],
      seanceFaite:new Date().toDateString(),seances:(p.seances||0)+1,
      stars:{...(p.stars||{}),[S.id]:Math.max(3,(p.stars||{})[S.id]||0)}}));
  };

  /* La part d'XP d'un temps. Le reliquat est soldé par finir(), donc la
     somme versée par une séance vaut toujours exactement S.xp. */
  const partXP=n>0?Math.floor(S.xp/n):S.xp;

  /* Un temps validé : on le coche, on verse sa part d'XP, et on s'arrête sur
     le palier — dans la séance, pas à l'accueil. Rien ne s'enchaîne tout
     seul, mais le suivant est à un tap. Si c'était le dernier, on ouvre
     directement le mot de la fin. */
  const validerTemps=(k)=>{
    const faits=tempsFaitsDe(st,S.id);
    const neuf=!faits.includes(k);
    const tous=neuf?[...faits,k]:faits;
    if(tous.length>=n){
      setSt(p=>({...p,tempsFaits:{...(p.tempsFaits||{}),[S.id]:tous}}));
      finir();aller(n);return;
    }
    /* Une séance déjà terminée qu'on refait ne redonne pas d'XP. */
    const gagne=(neuf&&!done)?partXP:0;
    setSt(p=>({...p,tempsFaits:{...(p.tempsFaits||{}),[S.id]:tous},
      ...(gagne?{xp:p.xp+gagne,weekXP:(p.weekXP||0)+gagne,
        xpSeance:{...(p.xpSeance||{}),[S.id]:((p.xpSeance||{})[S.id]||0)+gagne}}:{})}));
    SFX.success&&SFX.success();
    setPalier({k,xp:gagne,faits:tous.length});
    window.scrollTo(0,0);
  };

  /* La trace n'est pas une étape imposée : elle reste offerte à la fin,
     pour celles et ceux qui veulent s'entendre progresser. */
  const garderTrace=async(blob)=>{
    try{
      await carnetPoser({id:S.id+"-"+Date.now(),seance:S.id,titre:S.title,domaine:"j",
        type:(S.trace&&S.trace.type)||"audio",blob:blob||null,
        texte:(S.trace&&S.trace.type==="ecrit")?traceTexte:"",date:new Date().toISOString()});
    }catch(e){}
    setTraceFaite(true);setTraceOuverte(false);SFX.success&&SFX.success();
  };

  const aller=(t)=>{setTemps(t);window.scrollTo(0,0)};

  /* Depuis le carton : on reprend là où on s'est arrêté. Si les cinq sont
     déjà faits, « Refaire » remet le compteur des temps à zéro. */
  const commencer=()=>{
    if(!solo){aller(0);return}
    const k=prochainTemps(st,S);
    if(k>=0){aller(k);return}
    setSt(p=>({...p,tempsFaits:{...(p.tempsFaits||{}),[S.id]:[]}}));
    aller(0);
  };

  /* ── Le carton d'ouverture ── */
  if(temps===-1)return(
    <div className="safe-b sous-barre" style={{minHeight:'100vh',position:'relative',overflow:'hidden'}}>
      <div className="back-bar"><button onClick={back}>{I.chL({size:16})} {seance?"Quitter la séance":"Retour"}</button></div>
      <div style={{position:'absolute',inset:'calc(var(--barre-haut) + 58px) 14px 14px',border:'1px solid rgba(224,184,78,.13)',
        borderRadius:6,pointerEvents:'none',zIndex:1}}/>
      <div className="mw" style={{padding:'22px 22px 110px',display:'flex',flexDirection:'column',minHeight:'72vh',position:'relative',zIndex:2}}>
        <div style={{flex:1,display:'flex',flexDirection:'column',justifyContent:'center',textAlign:'center',position:'relative'}}>
          <p className="eb eb-or" style={{animation:'fadeIn .6s ease both'}}>{S.jour?`Séance ${S.jour}`:"La séance du jour"}</p>
          <h1 className="heading" style={{fontSize:'clamp(28px,7.8vw,38px)',lineHeight:1.04,margin:'11px 0 0',
            animation:'fadeUp .8s cubic-bezier(.22,1,.36,1) .12s both'}}>{S.title}</h1>
          <div style={{width:40,height:1,background:'var(--gold)',opacity:.7,margin:'18px auto 0',animation:'trait-ouvre .7s ease .5s both'}}/>

          {/* Votre coach — l'avatar choisi à l'inscription — vous attend. */}
          {(()=>{const C=monCoach(st);return(
            <div style={{marginTop:22}}>
              <div style={{position:'relative',width:104,height:104,margin:'0 auto',
                animation:'rit-pose .8s cubic-bezier(.22,1,.36,1) .3s both'}}>
                <div style={{position:'absolute',inset:0,borderRadius:'50%',
                  background:'radial-gradient(circle at 50% 60%,rgba(224,184,78,.22),transparent 72%)',
                  animation:'rit-halo 3s ease-in-out .9s infinite'}}/>
                <div style={{position:'absolute',inset:0,borderRadius:'50%',border:'1px solid rgba(224,184,78,.25)'}}/>
                <div style={{position:'absolute',inset:'10px'}}><AvatarSVG id={C.avatar} size={84}/></div>
              </div>
              <p style={{fontSize:10,color:'var(--text-3)',marginTop:11,animation:'fadeIn .8s ease .9s both'}}>
                <span style={{color:'var(--gold)',fontWeight:700}}>{C.nom}</span> vous attend en scène.
              </p>
            </div>
          )})()}

          {/* Les cinq domaines de la journée, annoncés d'entrée : on sait
              exactement ce qu'on va toucher avant de commencer. */}
          <div style={{display:'flex',flexWrap:'wrap',gap:6,justifyContent:'center',marginTop:18,
            animation:'fadeUp .8s cubic-bezier(.22,1,.36,1) .45s both'}}>
            {TS.map((t,k)=>{
              const D=DOMAINES[t.dom]||{};
              const ok=solo&&tempsFaitsDe(st,S.id).includes(k);
              return<span key={k} style={{fontSize:9,fontWeight:700,letterSpacing:'.08em',padding:'5px 10px',
                borderRadius:20,color:ok?'var(--emerald)':D.teinte,background:'var(--w03)',
                display:'flex',alignItems:'center',gap:4,opacity:ok?.75:1,
                border:'1px solid '+(ok?'rgba(52,211,153,.25)':'var(--line)')}}>
                {ok?I.check({size:9,sw:2.6}):null}{(D.nom||"").toUpperCase()}</span>;
            })}
          </div>
          <p style={{fontSize:10.5,color:'var(--text-3)',marginTop:15,display:'flex',gap:9,justifyContent:'center',
            animation:'fadeIn .8s ease .7s both'}}>
            <span>{S.dur}</span><span style={{color:'var(--gold)',fontWeight:700}}>+{S.xp} XP</span>
          </p>
        </div>
        <button onClick={commencer} className="btn-gold" style={{width:'100%',padding:'15px 0',fontSize:13,letterSpacing:'.05em',
          animation:'btn-scale-in .7s cubic-bezier(.22,1,.36,1) .85s both'}}>
          {done?"Refaire la séance":(solo&&tempsFaitsDe(st,S.id).length>0?"Reprendre":"Commencer")}
        </button>
        {done&&<button onClick={back} style={{width:'100%',padding:'12px 0',marginTop:4,fontSize:11.5,fontWeight:700,color:'var(--text-2)',background:'none',border:'none',cursor:'pointer'}}>Retour</button>}
      </div>
    </div>
  );

  /* ── Le palier : entre deux temps, on ne quitte plus la séance ── */
  if(palier){
    const T=TS[palier.k]||{};
    const D=DOMAINES[T.dom]||DOMAINES.v;
    const faits=tempsFaitsDe(st,S.id);
    const k2=prochainTemps(st,S);
    const T2=k2>=0?TS[k2]:null;
    const D2=T2?(DOMAINES[T2.dom]||DOMAINES.v):null;
    const reste=Math.max(0,n-palier.faits);
    return(
      <div className="safe-b sous-barre" style={{minHeight:'100vh'}}>
        <div className="back-bar"><button onClick={back}>{I.chL({size:16})} Quitter la séance</button></div>
        <div className="mw" style={{padding:'22px 20px 40px',display:'flex',flexDirection:'column',minHeight:'70vh'}}>
          <div className="rail" style={{marginBottom:20}}>
            {TS.map((t,k)=>{const DD=DOMAINES[t.dom]||{};const ok=faits.includes(k);
              return<i key={k} className={ok?"ok":""} style={ok?{background:DD.teinte,opacity:.85}:undefined}/>;})}
          </div>
          <div style={{textAlign:'center',animation:'fadeUp .6s cubic-bezier(.22,1,.36,1) both'}}>
            <div style={{width:46,height:46,borderRadius:'50%',margin:'0 auto 13px',display:'flex',
              alignItems:'center',justifyContent:'center',color:D.teinte,
              background:'var(--w03)',border:'1px solid '+D.teinte}}>{I.check({size:20,sw:2.4})}</div>
            <p className="eb" style={{color:D.teinte}}>{D.long}</p>
            <h2 className="heading" style={{fontSize:'clamp(21px,5.8vw,26px)',margin:'8px 0 0',lineHeight:1.18}}>{T.titre}</h2>
            {palier.xp>0&&<p className="heading gold-shimmer" style={{fontSize:20,marginTop:11}}>+{palier.xp} XP</p>}
            <p style={{fontSize:11.5,color:'var(--text-3)',marginTop:11}}>
              {palier.faits} sur {n} · encore {reste} {reste>1?"exercices":"exercice"} avant la fin de la séance
            </p>
          </div>
          <div style={{flex:1,minHeight:20}}/>
          {T2
            ?<>
               <button onClick={()=>{setPalier(null);aller(k2)}} className="rang"
                 style={{cursor:'pointer',width:'100%',textAlign:'left',borderColor:'var(--line-s)',
                   background:'linear-gradient(120deg,rgba(224,184,78,.10),var(--bg-card) 70%)'}}>
                 <div className="rang-ic" style={{background:'var(--w03)',color:D2.teinte}}><EI e={D2.icon||S.icon} s={17}/></div>
                 <div style={{flex:1,minWidth:0}}>
                   <span className="eb eb-or" style={{marginBottom:3}}>On enchaîne</span>
                   <p className="rang-t" style={{overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{T2.titre}</p>
                   <p style={{fontSize:9.5,color:'var(--text-3)',marginTop:2}}>{D2.nom}</p>
                 </div>
                 <span className="rang-x" style={{color:'var(--gold)'}}>+{partXP}</span>
               </button>
               <button onClick={back} style={{width:'100%',padding:'13px 0',marginTop:6,fontSize:11.5,fontWeight:700,
                 color:'var(--text-2)',background:'none',border:'none',cursor:'pointer'}}>Je reprends plus tard</button>
             </>
            :<button onClick={back} className="btn-gold" style={{width:'100%',padding:'14px 0',fontSize:13}}>Retour au menu</button>}
        </div>
      </div>
    );
  }

  /* ── L'écran d'un temps ── */
  if(temps>=0&&temps<n){
    const T=TS[temps];
    const D=DOMAINES[T.dom]||DOMAINES.v;
    const dernier=temps===n-1;
    const quizFini=!T.quiz||T.quiz.every((q,i)=>quizRep[temps+"-"+i]!==undefined);

    /* Le coach d'abord, l'exercice ensuite. */
    if(intro)return<IntroCoach key={S.id+"-i-"+temps} T={T} S={S} st={st} onGo={()=>setIntro(false)}/>;

    /* Le rail prend la couleur de chaque domaine : on lit d'un coup d'œil
       où on en est dans les cinq. */
    /* En mode « un exercice », le rail montre les temps déjà validés (pas
       seulement ceux d'avant) : on revient au menu entre chaque, l'ordre
       de passage n'est plus forcément l'ordre de la liste. */
    const dejaFaits=tempsFaitsDe(st,S.id);
    const nbFaits=dejaFaits.filter(k=>k!==temps).length;
    const rail=(
      <div style={{marginBottom:16}}>
        <div className="rail">
          {TS.map((t,k)=>{
            const DD=DOMAINES[t.dom]||{};
            const ok=solo?dejaFaits.includes(k):k<temps;
            return<i key={k} className={ok?"ok":k===temps?"on":""}
              style={(ok||k===temps)?{background:DD.teinte,opacity:k===temps?1:.5}:undefined}/>;
          })}
        </div>
        <div style={{display:'flex',justifyContent:'space-between',alignItems:'baseline',marginTop:7}}>
          <p className="eb" style={{color:D.teinte}}>{D.long}</p>
          <p style={{fontSize:9,color:'var(--text-3)'}}>
            {solo?`Exercice ${nbFaits+1} sur ${n}`:`${temps+1} / ${n}`}
          </p>
        </div>
      </div>
    );

    const matiere=T.matiere&&(
      <div className="card" style={{padding:'14px 16px',marginBottom:14,borderColor:'var(--line-s)',
        animation:'fadeUp .55s cubic-bezier(.22,1,.36,1) .12s both'}}>
        <p className="eb eb-or" style={{marginBottom:7}}>{T.matiere.type==="phrase"?"La phrase":"Le texte"}</p>
        {T.matiere.type==="phrase"
          ?<p className="vers" style={{fontSize:19,lineHeight:1.45,color:'var(--text)'}}>« {T.matiere.contenu} »</p>
          :<p className="vers" style={{fontSize:15,lineHeight:1.75,color:'var(--text)',whiteSpace:'pre-line'}}>{T.matiere.contenu}</p>}
        {T.matiere.source&&<p style={{fontSize:9.5,color:'var(--text-3)',marginTop:9}}>{T.matiere.source}</p>}
      </div>
    );

    const suivant=()=>{
      marquerDomaine(T.dom);
      if(solo){validerTemps(temps);return}
      if(dernier){finir();aller(n)}
      else aller(temps+1);
    };
    /* Le dernier des cinq — pas forcément le dernier de la liste, puisqu'on
       peut les prendre dans l'ordre qu'on veut. */
    const boucle=solo?(dejaFaits.filter(k=>k!==temps).length>=n-1):dernier;
    const labelFin=boucle?"C'est fait — terminer la séance":"C'est fait";

    /* Une leçon de culture prend l'écran entier : lecture paginée puis quiz,
       avec ses propres boutons. La barre du bas de la séance disparaît, sinon
       on aurait deux « Suivant » qui ne font pas la même chose. */
    const estLecon=T.dom==="cu"&&Array.isArray(T.texte)&&T.texte.length>0;
    if(estLecon)return(
      <div className="sous-barre safe-b" style={{minHeight:'100vh'}}>
        <div className="back-bar"><button onClick={()=>(!solo&&temps===0)?aller(-1):back()}>{I.chL({size:16})} {solo?"Retour au menu":"Retour"}</button></div>
        <div className="mw" style={{padding:'16px 20px 40px'}}>
          {xpPop&&<XPPop n={xpGagne} done={()=>setXpPop(false)}/>}
          {rail}
          <TempsCulture key={S.id+"-cu-"+temps} T={T} S={S} teinte={D.teinte}
            labelFin={labelFin} onValider={suivant}/>
        </div>
      </div>
    );

    return(
      <div className="sous-barre" style={{minHeight:'100vh'}}>
        <div className="back-bar"><button onClick={()=>(!solo&&temps===0)?aller(-1):back()}>{I.chL({size:16})} {solo?"Retour au menu":(temps===0?"Retour":(seance?"Quitter la séance":"Retour"))}</button></div>
        <div className="mw" style={{padding:'16px 20px 0'}}>
          {xpPop&&<XPPop n={xpGagne} done={()=>setXpPop(false)}/>}
          {rail}
          <div key={temps} className="temps">
            {/* Le bandeau illustré du domaine : un exercice doit s'annoncer
                comme une leçon, pas arriver comme un paragraphe nu. Le dessin
                est celui du domaine, la couleur aussi — on sait d'un coup
                d'œil si l'on est dans le corps, la voix, le texte ou le jeu. */}
            <div className="ill-card" style={{marginBottom:15,minHeight:118,
              animation:'fadeUp .55s cubic-bezier(.22,1,.36,1) both',
              background:`linear-gradient(150deg, color-mix(in srgb, ${D.teinte} 22%, var(--bg-card)), var(--bg-card) 72%)`}}>
              <img src={`img/${D.dessin}.svg`} alt="" aria-hidden="true" decoding="async"
                onError={e=>{e.target.style.display='none'}}
                style={{position:'absolute',right:-16,bottom:-12,width:152,height:152,objectFit:'contain',
                  zIndex:2,pointerEvents:'none',opacity:.92}}/>
              <span className="ill-in" style={{padding:'16px 17px 15px'}}>
                <span className="eb" style={{color:D.teinte}}>{D.long}</span>
                <span className="heading" style={{display:'block',fontSize:19,marginTop:5,maxWidth:198}}>{T.titre}</span>
                {T.pourquoi&&<span className="vers" style={{display:'block',fontSize:11.5,
                  color:'rgba(242,240,234,.66)',marginTop:6,maxWidth:190,lineHeight:1.5}}>{T.pourquoi}</span>}
              </span>
            </div>
            {matiere}
            <div className="card" style={{padding:20,marginBottom:14}}>

              {/* Culture : on lit, on ne fait pas. */}
              {T.texte&&T.texte.map((p,k)=>(
                <p key={k} className="body" style={{fontSize:13.5,lineHeight:1.8,color:k===0?'var(--text)':'var(--text-2)',
                  marginBottom:13}}>{p}</p>
              ))}
              {/* La consigne en prose ne sert que lorsqu'il n'y a pas d'étapes :
                  sinon elle répète mot pour mot ce que la liste dit mieux. */}
              {T.consigne&&!T.etapes&&<p className="body" style={{fontSize:13.5,lineHeight:1.75,color:'var(--text)'}}>{T.consigne}</p>}

              {/* Les étapes, numérotées : on les suit debout, du coin de l'œil,
                  sans relire un pavé de prose au milieu de l'exercice. */}
              {T.etapes&&(
                <div style={{marginTop:2}}>
                  {T.etapes.map((e,k)=>(
                    <div key={k} style={{display:'flex',gap:11,alignItems:'flex-start',
                      padding:'9px 0',borderTop:k?'1px solid var(--line)':'none',
                      animation:`fadeUp .5s cubic-bezier(.22,1,.36,1) ${.2+k*.13}s both`}}>
                      <span style={{flexShrink:0,width:20,height:20,borderRadius:'50%',marginTop:1,
                        display:'flex',alignItems:'center',justifyContent:'center',fontSize:9.5,fontWeight:700,
                        background:`color-mix(in srgb, ${D.teinte} 16%, transparent)`,color:D.teinte}}>{k+1}</span>
                      <p className="body" style={{flex:1,fontSize:13,lineHeight:1.6,color:'var(--text)'}}>{e}</p>
                    </div>
                  ))}
                </div>
              )}

              {T.guide&&<Guide key={S.id+"-g-"+temps} plan={T.guide.plan} cycles={T.guide.cycles} onComplete={()=>{}}/>}
              {T.compteur&&<Compteur key={S.id+"-c-"+temps} total={T.compteur} onComplete={()=>{}}/>}

              {/* S'entendre : le seul exercice où l'on découvre quelque chose
                  au lieu de l'exécuter. Rien n'est envoyé nulle part, rien
                  n'est gardé — on écoute, et on efface. */}
              {T.enregistrement&&(
                <div style={{marginTop:17}}>
                  <div style={{display:'flex',gap:8,padding:'11px 13px',borderRadius:11,marginBottom:12,
                    background:'rgba(224,184,78,.05)',border:'1px solid var(--line)'}}>
                    <span style={{color:'var(--gold)',flexShrink:0,marginTop:1}}>{I.info({size:13,sw:1.5})}</span>
                    <p className="vers" style={{fontSize:12.5,color:'var(--text-2)',lineHeight:1.55}}>
                      {T.enregistrement.aide||"Enregistrez, puis réécoutez-vous. C'est en s'entendant qu'on entend ce qu'on fait. Rien n'est conservé."}
                    </p>
                  </div>
                  <Enregistreur key={S.id+"-e-"+temps} type={T.enregistrement.type||"audio"}
                    secs={T.enregistrement.secs||20} onPret={()=>{SFX.success&&SFX.success()}}/>
                </div>
              )}

              {T.question&&(<>
                {T.aide&&<div style={{display:'flex',gap:9,padding:'12px 14px',borderRadius:12,background:'rgba(224,184,78,.05)',border:'1px solid var(--line)',margin:'16px 0 13px'}}>
                  <span style={{color:'var(--gold)',flexShrink:0,marginTop:1}}>{I.info({size:13,sw:1.5})}</span>
                  <p className="vers" style={{fontSize:13.5,color:'var(--text-2)',lineHeight:1.55}}>{T.aide}</p>
                </div>}
                <textarea rows={4} defaultValue={reponses[temps]||""} onBlur={e=>setReponses(r=>({...r,[temps]:e.target.value}))}
                  placeholder="Écrivez ici — personne ne le lira, c'est votre carnet."
                  className="input-field" style={{resize:'vertical',lineHeight:1.6,marginTop:T.aide?0:16}}/>
              </>)}

              {/* Ce qui manquait le plus : savoir si on le fait bien. Un
                  exercice sans repère, c'est une consigne qu'on exécute sans
                  jamais savoir si ça a marché. */}
              {T.repere&&(
                <div style={{display:'flex',gap:9,marginTop:16,padding:'12px 14px',borderRadius:12,
                  animation:'fadeUp .5s ease .55s both',
                  background:'rgba(52,211,153,.05)',border:'1px solid rgba(52,211,153,.13)'}}>
                  <span style={{color:'var(--emerald)',flexShrink:0,marginTop:1}}>{I.check({size:13,sw:2.2})}</span>
                  <div>
                    <p className="eb" style={{color:'var(--emerald)',marginBottom:4}}>Vous y êtes quand</p>
                    <p className="body" style={{fontSize:12.5,lineHeight:1.6,color:'var(--text-2)'}}>{T.repere}</p>
                  </div>
                </div>
              )}
              {T.piege&&(
                <div style={{display:'flex',gap:9,marginTop:9,padding:'12px 14px',borderRadius:12,
                  animation:'fadeUp .5s ease .68s both',
                  background:'rgba(232,135,90,.05)',border:'1px solid rgba(232,135,90,.13)'}}>
                  <span style={{color:'var(--coral)',flexShrink:0,marginTop:1}}>{I.info({size:13,sw:1.7})}</span>
                  <div>
                    <p className="eb" style={{color:'var(--coral)',marginBottom:4}}>L'erreur classique</p>
                    <p className="body" style={{fontSize:12.5,lineHeight:1.6,color:'var(--text-2)'}}>{T.piege}</p>
                  </div>
                </div>
              )}

              {T.quiz&&<div style={{marginTop:18}}>
                {T.quiz.map((q,qi)=>{
                  const cle=temps+"-"+qi,rep=quizRep[cle];
                  return(
                    <div key={qi} style={{marginBottom:qi<T.quiz.length-1?20:4}}>
                      <p style={{fontSize:13,fontWeight:700,lineHeight:1.5,marginBottom:10}}>{q.q}</p>
                      {q.o.map((o,oi)=>{
                        const choisi=rep===oi,bon=oi===q.a,montre=rep!==undefined;
                        return(
                          <button key={oi} disabled={montre} onClick={()=>{setQuizRep(r=>({...r,[cle]:oi}));oi===q.a?(SFX.success&&SFX.success()):(SFX.tap&&SFX.tap())}}
                            style={{width:'100%',textAlign:'left',padding:'11px 13px',marginBottom:7,borderRadius:11,cursor:montre?'default':'pointer',
                              fontSize:12.5,lineHeight:1.4,transition:'all .25s',
                              background:montre&&bon?'rgba(52,211,153,.10)':montre&&choisi?'rgba(224,120,100,.10)':'var(--w03)',
                              border:'1.5px solid '+(montre&&bon?'var(--emerald)':montre&&choisi?'var(--coral)':'var(--line)'),
                              color:montre&&(bon||choisi)?'var(--text)':'var(--text-2)',fontWeight:montre&&bon?700:500}}>
                            {o}
                          </button>
                        );
                      })}
                    </div>
                  );
                })}
              </div>}
            </div>
          </div>
        </div>
        <div style={{height:'calc(11rem + env(safe-area-inset-bottom,0px))'}}/>
        <div style={{position:'fixed',left:0,right:0,zIndex:49,padding:'22px 20px 12px',
          bottom:'calc(4.4rem + env(safe-area-inset-bottom,0px))',
          background:'linear-gradient(180deg,rgba(10,14,28,0),var(--bg) 42%)',pointerEvents:'none'}}>
          <div className="mw" style={{pointerEvents:'auto',display:'flex',justifyContent:'space-between',alignItems:'center',gap:10}}>
            {/* Un exercice = un écran = un bouton. Rien qui enchaîne tout seul. */}
            {solo
              ?<button onClick={suivant} className="btn-gold" style={{width:'100%',padding:'14px 0',fontSize:12.5,
                  opacity:quizFini?1:.4,pointerEvents:quizFini?'auto':'none'}}>
                 {labelFin}
               </button>
              :<>
                <button onClick={()=>temps>0?aller(temps-1):aller(-1)} className="btn-outline" style={{padding:'11px 17px',fontSize:10.5}}>← Précédent</button>
                <button onClick={suivant} className="pill" style={{opacity:quizFini?1:.4,pointerEvents:quizFini?'auto':'none'}}>
                  {dernier?"C'est fait":"Suivant"}
                </button>
               </>}
          </div>
        </div>
      </div>
    );
  }

  /* ── Le mot de la fin ── */
  return(
    <div className="safe-b" style={{minHeight:'100vh',background:'radial-gradient(ellipse at 50% 22%,rgba(224,184,78,.09),var(--bg) 60%)',
      display:'flex',flexDirection:'column',alignItems:'center',justifyContent:'center',
      padding:'calc(var(--barre-haut) + 30px) 26px calc(40px + env(safe-area-inset-bottom,0px))',textAlign:'center'}}>
      {xpPop&&<XPPop n={xpGagne} done={()=>setXpPop(false)}/>}
      <Confetti count={26} duration={2400}/>
      {/* Votre coach salue avec vous. */}
      {(()=>{const C=monCoach(st);return(
        <div style={{position:'relative',width:98,height:98,marginBottom:8,
          animation:'rit-pose .7s cubic-bezier(.22,1,.36,1) .1s both'}}>
          <div style={{position:'absolute',inset:0,borderRadius:'50%',
            background:'radial-gradient(circle at 50% 60%,rgba(224,184,78,.24),transparent 72%)'}}/>
          <div style={{position:'absolute',inset:0,borderRadius:'50%',border:'1px solid rgba(224,184,78,.25)'}}/>
          <div style={{position:'absolute',inset:'9px'}}><AvatarSVG id={C.avatar} size={80}/></div>
        </div>
      )})()}
      <p className="eb eb-or" style={{animation:'fadeIn .6s ease both'}}>Séance terminée</p>
      <h2 className="heading" style={{fontSize:26,margin:'9px 0 0',animation:'fadeUp .7s cubic-bezier(.22,1,.36,1) .1s both'}}>{S.title}</h2>
      <p className="heading gold-shimmer" style={{fontSize:23,marginTop:11,animation:'fadeUp .7s cubic-bezier(.22,1,.36,1) .2s both'}}>+{S.xp} XP</p>

      {/* Les cinq domaines touchés : la récompense du jour, en une ligne. */}
      <div style={{display:'flex',gap:6,justifyContent:'center',marginTop:16,flexWrap:'wrap',
        animation:'fadeUp .7s cubic-bezier(.22,1,.36,1) .3s both'}}>
        {TS.map((t,k)=>{
          const D=DOMAINES[t.dom]||{};
          return<span key={k} style={{fontSize:9,fontWeight:700,letterSpacing:'.06em',padding:'5px 9px',borderRadius:20,
            color:D.teinte,background:'var(--w03)',border:'1px solid var(--line-s)',display:'flex',alignItems:'center',gap:4}}>
            {I.check({size:10,sw:2.6})}{(D.nom||"").toUpperCase()}</span>;
        })}
      </div>

      <div style={{width:38,height:1,background:'var(--gold)',opacity:.65,margin:'22px 0',animation:'trait-ouvre .7s ease .4s both'}}/>
      <div className="card" style={{padding:'17px 19px',maxWidth:340,textAlign:'left',borderColor:'var(--line-s)',
        background:'linear-gradient(120deg,rgba(224,184,78,.06),var(--bg-card) 72%)',animation:'fadeUp .7s cubic-bezier(.22,1,.36,1) .5s both'}}>
        <p className="eb eb-or" style={{marginBottom:7}}>Le mot de la fin</p>
        <p className="body" style={{fontSize:12.5,lineHeight:1.7,color:'var(--text-2)'}}>{S.mot}</p>
      </div>
      {S.tip&&<div style={{maxWidth:340,marginTop:11,padding:'14px 17px',borderRadius:12,background:'rgba(200,164,78,.03)',
        border:'1px solid rgba(200,164,78,.08)',textAlign:'left',animation:'fadeUp .7s cubic-bezier(.22,1,.36,1) .62s both'}}>
        <p className="label-gold" style={{marginBottom:4}}>LE SAVIEZ-VOUS</p>
        <p className="body" style={{fontSize:10.5,lineHeight:1.6}}>{S.tip}</p>
      </div>}

      {traceFaite
        ?<p style={{fontSize:10.5,color:'var(--emerald)',marginTop:16,display:'flex',alignItems:'center',gap:6,
            animation:'fadeIn .5s ease both'}}>{I.check({size:12,sw:2})} Rangé dans votre carnet</p>
        :S.trace&&(traceOuverte
          ?<div style={{width:'100%',maxWidth:340,marginTop:16,textAlign:'left',animation:'fadeUp .5s cubic-bezier(.22,1,.36,1) both'}}>
             <p style={{fontSize:11.5,color:'var(--text-2)',lineHeight:1.6,marginBottom:11}}>{S.trace.consigne}</p>
             {S.trace.type==="ecrit"
               ?<>
                  <textarea rows={4} value={traceTexte} onChange={e=>setTraceTexte(e.target.value)}
                    placeholder="Trois lignes suffisent." className="input-field"
                    style={{resize:'vertical',lineHeight:1.6,marginBottom:10}}/>
                  <button onClick={()=>garderTrace(null)} className="pill"
                    style={{width:'100%',padding:'11px 0',opacity:traceTexte.trim().length>3?1:.4,
                      pointerEvents:traceTexte.trim().length>3?'auto':'none'}}>Garder</button>
                </>
               :<Enregistreur type={S.trace.type} secs={S.trace.secs} onPret={garderTrace}/>}
             <button onClick={()=>setTraceOuverte(false)} style={{width:'100%',padding:'10px 0',marginTop:5,fontSize:10.5,
               fontWeight:700,color:'var(--text-3)',background:'none',border:'none',cursor:'pointer'}}>Non merci</button>
           </div>
          :<button onClick={()=>setTraceOuverte(true)}
             style={{marginTop:17,fontSize:11,fontWeight:700,color:'var(--text-3)',background:'none',border:'none',
               cursor:'pointer',padding:'8px 0',textDecoration:'underline',textUnderlineOffset:3,
               animation:'fadeIn .6s ease .9s both'}}>
             Garder une trace de cette séance — facultatif
           </button>)}

      <div style={{width:'100%',maxWidth:340,marginTop:26,animation:'fadeUp .7s cubic-bezier(.22,1,.36,1) .78s both'}}>
        {next
          ?<>
            <button onClick={()=>{onNext&&onNext()}} className="rang"
              style={{cursor:'pointer',borderColor:'var(--line-s)',background:'linear-gradient(120deg,rgba(224,184,78,.10),var(--bg-card) 70%)',textAlign:'left'}}>
              <div className="rang-ic" style={{background:'rgba(224,184,78,.16)',color:'var(--gold)'}}><EI e={next.icon} s={17}/></div>
              <div style={{flex:1,minWidth:0}}>
                <span className="eb eb-or" style={{marginBottom:3}}>{seance?`Étape ${seance.i+1} sur ${seance.n}`:"La séance suivante"}</span>
                <p className="rang-t" style={{overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{next.title}</p>
                <p style={{fontSize:9.5,color:'var(--text-3)',marginTop:2}}>{next.cat} · {next.dur}</p>
              </div>
              <span className="rang-x" style={{color:'var(--gold)'}}>+{next.xp}</span>
            </button>
            <button onClick={back} style={{width:'100%',padding:'12px 0',marginTop:4,fontSize:11.5,fontWeight:700,color:'var(--text-2)',background:'none',border:'none',cursor:'pointer'}}>
              J'arrête ici pour aujourd'hui
            </button>
          </>
          :<button onClick={back} className="btn-gold" style={{width:'100%',padding:'14px 0',fontSize:13}}>Continuer</button>}
      </div>
    </div>
  );
}

/* ═══ LE CARNET, dans le profil ═══ */
function Carnet({onClose}){
  const[traces,setTraces]=useState(null);
  const[urls,setUrls]=useState({});
  useEffect(()=>{let vivant=true;
    carnetLire().then(t=>{if(!vivant)return;setTraces(t);
      const u={};t.forEach(x=>{if(x.blob)u[x.id]=URL.createObjectURL(x.blob)});setUrls(u)})
      .catch(()=>setTraces([]));
    return()=>{vivant=false}},[]);
  const effacer=async(id)=>{await carnetEffacer(id);setTraces(t=>t.filter(x=>x.id!==id))};
  const jour=d=>new Date(d).toLocaleDateString('fr-FR',{day:'numeric',month:'long'});

  return(
    <div className="safe-b fade-up sous-barre" style={{minHeight:'100vh'}}>
      <div className="back-bar"><button onClick={onClose}>{I.chL({size:16})} Retour</button></div>
      <div className="mw" style={{padding:'16px 20px 110px'}}>
        <h1 className="heading" style={{fontSize:26,marginBottom:5}}>Votre carnet</h1>
        <p className="body" style={{fontSize:12,marginBottom:22}}>Ce que vous avez enregistré séance après séance. Tout reste sur cet appareil.</p>
        {traces===null&&<p style={{fontSize:12,color:'var(--text-3)'}}>Ouverture du carnet…</p>}
        {traces&&traces.length===0&&(
          <div className="card" style={{padding:24,textAlign:'center'}}>
            <p className="body" style={{fontSize:12.5,lineHeight:1.7,color:'var(--text-2)'}}>
              Le carnet est encore vide. À la fin de chaque séance, on vous demande une trace — trente secondes de voix, une vidéo, trois lignes écrites.
              C'est là qu'on voit le chemin parcouru, et nulle part ailleurs.
            </p>
          </div>
        )}
        {traces&&traces.map(t=>(
          <div key={t.id} className="card" style={{padding:'15px 16px',marginBottom:11}}>
            <div style={{display:'flex',justifyContent:'space-between',alignItems:'baseline',gap:10,marginBottom:9}}>
              <div style={{minWidth:0}}>
                <p className="eb eb-or">{(DOMAINES[t.domaine]||{}).nom||"Séance"}</p>
                <p className="rang-t" style={{marginTop:3}}>{t.titre}</p>
              </div>
              <p style={{fontSize:9.5,color:'var(--text-3)',flexShrink:0}}>{jour(t.date)}</p>
            </div>
            {t.type==="audio"&&urls[t.id]&&<Lecteur src={urls[t.id]}/>}
            {t.type==="video"&&urls[t.id]&&<video src={urls[t.id]} controls playsInline style={{width:'100%',maxWidth:220,borderRadius:12,background:'#000'}}/>}
            {t.type==="ecrit"&&<p className="vers" style={{fontSize:14,lineHeight:1.7,color:'var(--text-2)',whiteSpace:'pre-line'}}>{t.texte}</p>}
            {!urls[t.id]&&t.type!=="ecrit"&&<p style={{fontSize:11,color:'var(--text-3)'}}>Fait, sans enregistrement.</p>}
            <button onClick={()=>effacer(t.id)} style={{marginTop:10,fontSize:10,color:'var(--text-3)',background:'none',border:'none',cursor:'pointer',fontWeight:700}}>Supprimer</button>
          </div>
        ))}
      </div>
    </div>
  );
}


