            <span style={{width:18,height:18,borderRadius:9,background:'#fff',boxShadow:'0 1px 3px rgba(0,0,0,.3)',transform:st.notifsOff?'translateX(18px)':'translateX(0)',transition:'transform .3s'}}/>
